word-count.source:
def solve(words):
 d={}
 for word in words:
  word=word.lower()
  d[word]=d.get(word,0)+1
 return d

def solve(words):
 d={}
 for word in words:
  if word: d[word]=d.get(word,0)+1
 return d

normalize-rows.source:
def solve(matrix):
 total=sum(map(sum,matrix))
 return [[x/total if total else 0 for x in row] for row in matrix]
